int count_partitions(int n) {
    std::vector<int> ways(n + 1, 0);
    ways[0] = 1;
    for (int part = 1; part <= n; ++part) {
        for (int value = part; value <= n; ++value) {
            ways[value] += ways[value - part];
        }
    }
    return ways[n];
}

